nBatchHashes\\\": true,\\n  \\\"privateSigningMaterialRoundtrip\\\": true,\\n  \\\"originalStartHashVerified\\\": true,\\n  \\\"startLedger\\\": {\\n    \\\"frozenEligible\\\": 2,\\n    \\\"reserved\\\": 1,\\n    \\\"skippedWithdrawn\\\": 1,\\n    \\\"cancelled\\\": 0,\\n    \\\"accepted\\\": 0,\\n    \\\"applied\\\": 0,\\n    \\\"failed\\\": 0,\\n    \\\"unknown\\\": 0,\\n    \\\"disputed\\\": 0\\n  },\\n  \\\"projectionLedger\\\": {\\n    \\\"frozenEligible\\\": 2,\\n    \\\"reserved\\\": 0,\\n    \\\"skippedWithdrawn\\\": 1,\\n    \\\"cancelled\\\": 0,\\n    \\\"accepted\\\": 0,\\n    \\\"applied\\\": 0,\\n    \\\"failed\\\": 0,\\n    \\\"unknown\\\": 1,\\n    \\\"disputed\\\": 0\\n  },\\n  \\\"skippedWithdrawalSequence\\\": 9,\\n  \\\"startSequence\\\": 10,\\n  \\\"unknownKeepsReservationHeld\\\": true,\\n  \\\"originalStartRemainsReserved\\\": true,\\n  \\\"projectionKeepsOriginalHash\\\": true,\\n  \\\"privateReasonAbsentFromPublicView\\\": true,\\n  \\\"savedObservationHashVerified\\\": true,\\n  \\\"sourceHashes\\\": {\\n    \\\"services/aos-api/aos_api/ecommerce_workshop_customer_contact.py\\\": \\\"afae8d6baf95c977a176efa67b56ca3877351dd1c819fb8723d28dc68a06a9b3\\\",\\n    \\\"services/aos-api/aos_api/ecommerce_workshop_customer_lifecycle.py\\\": \\\"0c1cb897d99b622d041d65688bedceedd5697da1fdd6152844fcd0e2bfa3ac4d\\\"\\n  },\\n  \\\"wholeGoalComplete\\\": false\\n}\\n\\nEVIDENCE .evidence/qyh-customer-contact-read-admission-20261015/reader-scope-readback-r1.json\\n{\\n  \\\"authority\\\": \\\"AOS-002037\\\",\\n  \\\"reader\\\": {\\n    \\\"schema\\\": \\\"aos-memory-task-receipt/v1\\\",\\n    \\\"task_id\\\": \\\"qyh-customer-contact-bounded-reader-20261015\\\",\\n    \\\"owner\\\": \\\"codex-01a13484-f019-7d82-94ce-812396db9124\\\",\\n    \\\"base_revision\\\": \\\"AOS-002037\\\",\\n    \\\"scope\\\": [\\n      \\\"aos-platform/services/aos-api/aos_api/ecommerce_customer_contact_readonly.py\\\",\\n      \\\"aos-platform/services/aos-api/tests/test_ecommer